import { test, expect } from '@playwright/test';

test.describe('Search functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should update search results as user types', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });
    await searchInput.fill('Playwright');

    // Wait for 300ms to simulate debounce
    await page.waitForTimeout(300);

    const results = page.getByRole('list', { name: /search results/i });
    await expect(results).toContainText('Playwright Test');
  });

  test('should not update results immediately on rapid input', async ({ page }) => {
    const searchInput = page.getByRole('textbox', { name: /search/i });
    await searchInput.fill('Play');

    // Wait for less than debounce time
    await page.waitForTimeout(100);

    const results = page.getByRole('list', { name: /search results/i });
    await expect(results).not.toContainText('Playwright Test');

    // Now wait for the debounce time and check again
    await page.waitForTimeout(300);
    await expect(results).toContainText('Playwright Test');
  });
});
